using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Net;using System.Net.Sockets;using System.Threading;using System.Threading.Tasks;using System.Diagnostics;using System.Web.Script.Serialization;using SplifyWin;
class VpnDnsRegression20261023 {
 static JavaScriptSerializer json=new JavaScriptSerializer();static int count;
 static void Check(bool good,string label){if(!good)throw new Exception(label);Console.WriteLine("PASS "+(++count)+" "+label);}
 static Dictionary<string,object> Route(Dictionary<string,object> c){return (Dictionary<string,object>)c["route"];}
 static List<Dictionary<string,object>> Rules(Dictionary<string,object> c){return ((IEnumerable)Route(c)["rules"]).Cast<Dictionary<string,object>>().ToList();}
 static int Port(){var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();int p=((IPEndPoint)listener.LocalEndpoint).Port;listener.Stop();return p;}
 static void Exact(NetworkStream s,byte[] b){int n=0;while(n<b.Length){int r=s.Read(b,n,b.Length-n);if(r==0)throw new IOException("EOF");n+=r;}}
 static bool Request(int port){try{using(var c=new TcpClient("127.0.0.1",port)){c.ReceiveTimeout=5000;var s=c.GetStream();s.Write(new byte[]{5,1,0},0,3);var auth=new byte[2];Exact(s,auth);s.Write(new byte[]{5,1,0,1,127,0,0,2,0,53},0,10);var answer=new byte[10];Exact(s,answer);if(answer[1]!=0)return false;s.WriteByte(42);return s.ReadByte()==42;}}catch(IOException){return false;}}
 static ClientState State(){var n=Links.Read("socks5://127.0.0.1:19999").Single();return new ClientState{Mode="tun",AutoSelect=false,Servers=new List<ServerNode>{n},SelectedServerId=n.Id,IndependentWarpOutputs=true,VpnEnabled=true};}
 static void Dispatch(NetworkCore core,ClientState state,string root){
  var dns=new TcpListener(IPAddress.Parse("127.0.0.2"),53);dns.Start();var echo=Task.Run(()=>{using(var c=dns.AcceptTcpClient()){c.ReceiveTimeout=5000;var s=c.GetStream();int value=s.ReadByte();s.WriteByte((byte)value);}});
  try{foreach(bool guard in new[]{false,true}){var config=core.Build(state);var rules=Rules(config);rules.RemoveAll(r=>r.ContainsKey("ip_cidr")&&r.ContainsKey("port"));if(guard)rules.Add(VpnDnsBootstrap.Rule(new[]{"127.0.0.2"}));Route(config)["rules"]=rules;int port=Port();config["inbounds"]=new[]{new Dictionary<string,object>{{"type","mixed"},{"tag","tun-in"},{"listen","127.0.0.1"},{"listen_port",port}}};config.Remove("experimental");string file=Path.Combine(root,guard?"dns-after.json":"dns-before.json");File.WriteAllText(file,json.Serialize(config));core.Check(file);
   var psi=new ProcessStartInfo(core.Executable,"--disable-color run -c \""+file+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};using(var p=Process.Start(psi)){var stdout=p.StandardOutput.ReadToEndAsync();var stderr=p.StandardError.ReadToEndAsync();try{bool ready=false;var end=DateTime.UtcNow.AddSeconds(5);while(!ready&&DateTime.UtcNow<end){try{using(var c=new TcpClient("127.0.0.1",port))ready=true;}catch(SocketException){Thread.Sleep(25);}}if(!ready)throw new Exception("Core listener");Check(Request(port)==guard,guard?"actual core reaches OS DNS endpoint directly after fix":"reproduced: OS DNS endpoint incorrectly follows dead VPN without guard");}finally{if(!p.HasExited){p.Kill();p.WaitForExit(2000);}Task.WaitAll(new Task[]{stdout,stderr},2000);File.WriteAllText(Path.Combine(root,guard?"dns-after.log":"dns-before.log"),stdout.Result+stderr.Result);}}}
   Check(echo.Wait(3000),"local DNS-port echo confirmed; no real DNS or system route changed");
  }finally{dns.Stop();}
 }
 static int Main(string[] args){try{string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);RuntimeResources.Prepare(root);var core=new NetworkCore(new StateStore(root));var state=State();var config=core.Build(state);var chosen=((IEnumerable) ((Dictionary<string,object>)config["dns"])["servers"]).Cast<Dictionary<string,object>>().Single(d=>Convert.ToString(d["tag"])=="chosen");Check(Convert.ToString(chosen["detour"])=="node-1","public DNS follows selected VPN instead of implicit direct");core.Check(core.WriteConfig(state));Check(true,"actual core accepts remote DNS detour");state.VpnEnabled=false;chosen=((IEnumerable)((Dictionary<string,object>)core.Build(state)["dns"])["servers"]).Cast<Dictionary<string,object>>().Single(d=>Convert.ToString(d["tag"])=="chosen");Check(!chosen.ContainsKey("detour"),"standalone disabled VPN retains independent DNS");state=State();state.DnsProvider="Системный";state.DnsProtocol="Системный";
  state.ExcludedApplications=new List<string>{"fixture.exe"};var excluded=Rules(core.Build(state));int sniff=excluded.FindIndex(r=>r.ContainsKey("process_name")&&Convert.ToString(r["action"])=="sniff"),direct=excluded.FindIndex(r=>r.ContainsKey("process_name")&&r.ContainsKey("outbound")&&Convert.ToString(r["outbound"])=="direct");Check(sniff>=0&&direct==sniff+1,"excluded apps are sniffed only for Fake-IP recovery, retaining immediate direct decision");Check(direct<excluded.FindIndex(r=>Convert.ToString(r["action"])=="sniff"&&!r.ContainsKey("process_name")),"explicit app exclusion retains priority over generic routing");core.Check(core.WriteConfig(state));Check(true,"actual core accepts guarded excluded-app sniff and direct rules");state.ExcludedApplications.Clear();
  var guard=VpnDnsBootstrap.Rule(new[]{"192.168.1.1","192.168.1.1","2001:db8::53","invalid"});Check(((string[])guard["ip_cidr"]).Length==2&&((int[])guard["port"]).Single()==53,"bootstrap guard is exact, deduplicated IPv4/IPv6 DNS endpoints only");Check(VpnDnsBootstrap.Rule(new string[0])==null,"no empty match-all direct rule");
  Check(!((string[])VpnDnsBootstrap.Rule(new[]{"fe80::1%12"})["ip_cidr"]).Single().Contains("%"),"Windows scoped IPv6 DNS becomes a valid sing-box CIDR");
  state.Lists.Add(new RouteList{Name="explicit block",Target="block",Text="192.168.1.1/32"});config=core.Build(state);var rules=Rules(config);rules.Add(guard);Check(rules.FindIndex(r=>r.ContainsKey("outbound")&&Convert.ToString(r["outbound"])=="block")<rules.Count-1,"explicit user rule retains priority over bootstrap fallback");state.Lists.Clear();Dispatch(core,state,root);Check(Convert.ToString(Route(core.Build(state))["final"])=="node-1","no-rules internet fallback remains VPN, not direct");Console.WriteLine("RESULT "+count+" PASS");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
